  assert.equal(fatorial(5), 120);
});

test('fatorial recusa entradas inválidas', () => {
  assert.throws(() => fatorial(-1));
  assert.throws(() => fatorial(2.5));
  assert.throws(() => fatorial('5'));
});

test('fibonacci segue a sequência a partir do zero', () => {
  assert.equal(fibonacci(0), 0);
  assert.equal(fibonacci(1), 1);
  assert.equal(fibonacci(10), 55);
});

