export function fatorial(n) {
  if (typeof n !== 'number' || n < 0 || !Number.isInteger(n)) {
    throw new Error('n precisa ser um inteiro >= 0');
  }
  if (n === 0) {
    return 1;
  }
  return n * fatorial(n - 1);
}

export function fibonacci(posicao) {
  if (typeof posicao !== 'number' || posicao < 0 || !Number.isInteger(posicao)) {
    throw new Error('posicao precisa ser um inteiro >= 0');
  }
  if (posicao === 0) {
    return 0;
  }
  if (posicao === 1) {
    return 1;
  }
  return fibonacci(posicao - 1) + fibonacci(posicao - 2);
}
